// 角色名到 GSOV 权重的自动配对。
//
// 从整合包里扫描出来的候选权重自带一个**配对键** (`ModelCandidate.key`: 权重文件名去掉
// 训练后缀与扩展名, 例如 `爱音-e15.ckpt` / `爱音_e4_s436_l64.pth` -> `爱音`)。
// 导入角色后按这个键与角色名配对, 用户就不用一个个手选 —— 训练产物与角色本来就是同一个人。
//
// 只做**可信**配对: 完全相同, 或者一方包含另一方 (「千早爱音」与 `爱音`)。键太短
// (单字符) 不参与, 否则 `A` 会命中一堆东西。配错比不配更难查: 界面看起来"已经选好了",
// 实际用的是别人的音色。

import type { ModelCandidate } from '../commands/voice';

/** 参与包含关系匹配的最短长度 (与对话者匹配保持同一条底线) */
const MIN_PARTIAL = 2;

/** 名称归一化: 大小写、空白无关 */
function normalize(value: string): string {
  return value.trim().toLowerCase().replace(/\s+/g, '');
}

/** 为角色名挑一个候选权重; 没有可信匹配时返回 null */
export function pickModel(name: string, candidates: ModelCandidate[]): ModelCandidate | null {
  const target = normalize(name);
  if (!target) return null;

  // 一、完全相同
  const exact = candidates.find((candidate) => normalize(candidate.key) === target);
  if (exact) return exact;

  // 二、互相包含 (取命中更长的一方, 长度相同则视为有歧义, 不猜)
  let best: ModelCandidate | null = null;
  let bestLength = 0;
  let tied = false;
  for (const candidate of candidates) {
    const key = normalize(candidate.key);
    if (key.length < MIN_PARTIAL) continue;
    const overlap = target.includes(key) ? key.length : key.includes(target) ? target.length : 0;
    if (overlap === 0) continue;
    if (overlap > bestLength) {
      best = candidate;
      bestLength = overlap;
      tied = false;
    } else if (overlap === bestLength) {
      tied = true;
    }
  }
  return tied ? null : best;
}
